const express = require('express');
const { Pool } = require('pg');
const QueryStream = require('pg-query-stream');
const { jwtAuth } = require('../auth');

const router = express.Router();
const pool = new Pool();

router.get('/api/vaults/:vaultId/audit-stream', jwtAuth, async (req, res) => {
  const { vaultId } = req.params;

  const accessCheck = await pool.query(
    'SELECT id FROM vault_members WHERE vault_id = $1 AND user_id = $2 AND role = $3',
    [vaultId, req.user.id, 'VAULT_ADMIN']
  );
  if (!accessCheck.rows.length) {
    return res.status(403).json({ error: 'Forbidden: requires VAULT_ADMIN access to stream audit logs' });
  }

  res.writeHead(200, {
    'Content-Type': 'application/x-ndjson',
    'Transfer-Encoding': 'chunked',
    'Cache-Control': 'no-cache',
  });

  const client = await pool.connect();
  const query = new QueryStream('SELECT * FROM vault_secret_access_logs WHERE vault_id = $1 ORDER BY accessed_at DESC', [vaultId]);
  const stream = client.query(query);

  stream.on('data', (row) => {
    res.write(JSON.stringify(row) + '\n');
  });
  stream.on('end', () => {
    client.release();
    res.end();
  });
});
